<?php use App\Core\Auth; use App\Core\Csrf; use App\Core\View; ?>
<div class="page-header"><h1>Caixa</h1><a class="button primary" href="/pos">Ir ao PDV</a></div>
<?php if(!$current && !empty($takeover)): ?>
<div class="panel"><div class="panel-header">Caixa em uso</div><div class="panel-body">
<p>Este caixa já possui uma sessão aberta. <?= View::e($takeover['register_name']) ?> foi aberto por <?= View::e($takeover['user_name']) ?> em <?= View::e($takeover['opened_at']) ?>. Assumir continua as mesmas vendas e o mesmo caixa, sem abrir outra sessão.</p>
<form method="post" action="/cash/assume"><?= Csrf::field() ?><input type="hidden" name="session_id" value="<?= (int) $takeover['id'] ?>"><button class="primary" type="submit">Assumir caixa</button></form>
</div></div>
<?php endif ?>
<?php if(!$current): ?>
<div class="panel"><div class="panel-header">Abertura</div><div class="panel-body"><form method="post" action="/cash/open"><?= Csrf::field() ?>
<div class="grid three"><div class="field"><label>Caixa</label><select name="register_id" required><option value="">Selecione uma opção...</option><?php foreach($registers as $r): ?><option value="<?= (int)$r['id'] ?>"><?= View::e($r['name']) ?></option><?php endforeach ?></select></div><div class="field"><label>Fundo inicial</label><input name="amount" inputmode="decimal" data-mask="money" value="0,00" required placeholder="Ex.: 150,00"></div><div class="field"><label>Observação</label><input name="notes" placeholder="Ex.: Abertura do turno da manhã"></div></div><button class="primary">Abrir caixa</button></form></div></div>
<?php else: ?>
<div class="grid three"><div class="stat"><span>Caixa</span><strong><?= View::e($current['register_name']) ?></strong></div><div class="stat"><span>Fundo</span><strong>R$ <?= number_format($totals['opening'],2,',','.') ?></strong></div><div class="stat"><span>Dinheiro na gaveta</span><strong>R$ <?= number_format($totals['expected'],2,',','.') ?></strong></div></div>
<div class="panel"><div class="panel-header">Vendas deste caixa</div><div class="panel-body">
<?php $report = $sessionSales ?? ['sales'=>[],'by_method'=>[],'count'=>0,'total'=>0]; ?>
<p><?= (int) $report['count'] ?> venda(s) registrada(s) neste caixa, no total de R$ <?= number_format((float) $report['total'], 2, ',', '.') ?>. O dinheiro na gaveta só muda com venda em dinheiro, suprimento e sangria. PIX e cartão ficam nesta lista e em Vendas.</p>
<?php if ($report['by_method']): ?><p><?php foreach ($report['by_method'] as $method): ?><span class="muted"><?= View::e($method['name']) ?>: R$ <?= number_format($method['total'], 2, ',', '.') ?></span> <?php endforeach ?></p><?php endif ?>
<?php if (!$report['sales']): ?><p class="muted">Nenhuma venda gravada nesta sessão.</p><?php else: ?>
<div class="table-wrap"><table><thead><tr><th>Número</th><th>Hora</th><th>Pagamento</th><th>Status</th><th class="num">Total</th></tr></thead><tbody>
<?php foreach ($report['sales'] as $sale): ?><tr><td><a href="/sales?receipt=<?= (int) $sale['id'] ?>"><?= View::e($sale['sale_number']) ?></a></td><td><?= View::e($sale['completed_at']) ?></td><td><?= View::e($sale['methods']) ?></td><td><?= View::e($sale['status']) ?></td><td class="num">R$ <?= number_format((float) $sale['total'], 2, ',', '.') ?></td></tr><?php endforeach ?>
</tbody></table></div><?php endif ?>
</div></div>
<?php if(Auth::can('cash.move')): ?><div class="panel"><div class="panel-header">Suprimento / sangria</div><div class="panel-body"><form method="post" action="/cash/move"><?= Csrf::field() ?><div class="grid three"><div class="field"><label>Tipo</label><select name="type"><option value="supply">Suprimento</option><option value="withdrawal">Sangria</option></select></div><div class="field"><label>Valor</label><input name="amount" data-mask="money" required placeholder="Ex.: 80,00"></div><div class="field"><label>Justificativa</label><input name="reason" minlength="5" required placeholder="Ex.: Sangria para o cofre"></div></div><button>Registrar</button></form></div></div><?php endif ?>
<?php if(Auth::can('cash.close')): ?><div class="panel"><div class="panel-header">Fechamento</div><div class="panel-body"><form method="post" action="/cash/close" data-confirm="Fechar este caixa agora? O documento de fechamento será aberto para impressão."><?= Csrf::field() ?><div class="grid two"><div class="field"><label>Dinheiro contado</label><input name="counted" data-mask="money" required placeholder="Ex.: 350,00"></div><div class="field"><label>Justificativa (obrigatória se divergir)</label><input name="reason" placeholder="Ex.: Informe o motivo se o valor divergir"></div></div><p class="muted">A confirmação é pedida uma vez. Depois o PDF do fechamento abre para impressão.</p><button class="danger">Fechar caixa</button></form></div></div><?php endif ?>
<?php endif ?>
<div class="panel"><div class="panel-header">Histórico</div><div class="panel-body table-wrap"><table><thead><tr><th>Caixa</th><th>Operador</th><th>Abertura</th><th>Fechamento</th><th class="num">Esperado</th><th class="num">Contado</th><th class="num">Diferença</th><th>Justificativa</th><th>Documento</th></tr></thead><tbody><?php foreach($history as $h): ?><tr><td><?= View::e($h['register_name']) ?></td><td><?= View::e($h['user_name']) ?></td><td><?= View::e($h['opened_at']) ?></td><td><?= View::e($h['closed_at']??'Aberto') ?></td><td class="num"><?= $h['expected_cash']===null?'—':'R$ '.number_format((float)$h['expected_cash'],2,',','.') ?></td><td class="num"><?= $h['counted_cash']===null?'—':'R$ '.number_format((float)$h['counted_cash'],2,',','.') ?></td><td class="num"><?= $h['difference_amount']===null?'—':'R$ '.number_format((float)$h['difference_amount'],2,',','.') ?></td><td><?= View::e($h['closing_reason']??'') ?></td><td><a href="/cash/pdf?id=<?= (int) $h['id'] ?>" target="_blank">PDF</a></td></tr><?php endforeach ?></tbody></table></div></div>
